const body = $input.item.json;
const audioUrl = body.audioUrl || body.audio_url || body.fileUrl || body.file_url || body.url;
let transcript = (body.transcript || body.text || body.transcript_text || '').trim();
if (!transcript && !audioUrl) {
  throw new Error('Please provide either transcript or audioUrl/audio_url/fileUrl/file_url.');
}
if (!transcript) {
  const transcriptionUrl = process.env.TRANSCRIPTION_API_URL || 'http://localhost:11434/v1/audio/transcriptions';
  const response = await this.helpers.request({
    method: 'POST',
    uri: transcriptionUrl,
    json: true,
    body: {
      audio_url: audioUrl,
      language: 'fa',
      response_format: 'text'
    }
  });
  transcript = typeof response === 'string' ? response : response.text || response.transcript || response.data || JSON.stringify(response);
}
return [{ json: { audioUrl, transcript, originalBody: body } }];

const aiResponse = $input.item.json;
let text = '';
if (aiResponse.choices?.[0]?.message) text = aiResponse.choices[0].message.content;
else if (aiResponse.choices?.[0]?.text) text = aiResponse.choices[0].text;
else if (typeof aiResponse === 'string') text = aiResponse;
else if (aiResponse.output) text = Array.isArray(aiResponse.output) ? aiResponse.output.map(o => o.content?.[0]?.text || '').join('') : JSON.stringify(aiResponse.output);
else text = JSON.stringify(aiResponse);
let parsed;
try {
  parsed = JSON.parse(text);
} catch (error) {
  parsed = { raw_text: text };
}
return [{ json: { analysis: parsed, raw: aiResponse } }];
